{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "Despite these scientific advancements on sustainability determinants, there is a lack of guidance on how to select the most appropriate theoretical approach to evaluate the sustainability of EBIs in healthcare. ... Most evaluations in this integrative review applied determinant theoretical approaches, that focus on predictors of sustainability (organizational, contextual, human, and processes), but they did not link these determinants to, and, or measure patient or system level outcomes, such as sustained patient or staff benefit [6].",
      "reason": "The text describes the current state of knowledge regarding sustainability evaluation (e.g., focus on determinants) and identifies important uncertainties/gaps (e.g., lack of guidance on selecting theoretical approaches, lack of linkage to patient/system outcomes)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "As evaluation is necessary to determine effectiveness, this review aimed to improve our understanding of how the sustainability of EBIs in healthcare is evaluated. A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research.",
      "reason": "The authors explain the importance of the review by stating that evaluation is necessary for effectiveness and that this review fills a gap by focusing on evaluation, which differentiates it from other syntheses."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "A focus on evaluation is what differentiates this review from recent syntheses published on approaches to sustainability research. ... These themes are similar to the work of Lennox et al. Most sustainability evaluations included in this study used qualitative research designs (48%), with interviews as the most common data collection method. This finding is consistent with the work of Lennox [6] who reported 59% of their included studies used qualitative methods.",
      "reason": "The authors acknowledge existing similar reviews (e.g., Lennox et al.) and explain the need for the current review by highlighting its specific focus on evaluation, which differentiates it from those previous syntheses."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is an integrative review of approaches to evaluate sustainability, not a review of the effects of a specific intervention; therefore, a mechanism of action for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is not evaluating a specific complex intervention or delivery context that requires a logic model; it is a methodological review of evaluation approaches."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The aim of this integrative review was to identify and synthesize approaches that have been used to evaluate the sustainability of EBIs in healthcare. We aimed to enhance our understanding of sustainability definitions, research designs, data collection methods, timing, measures, and sustainability outcomes used for sustainability evaluation studies.",
      "reason": "The review explicitly states its objectives in the 'Aim' section, clearly defining the purpose of the integrative review."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is an integrative review focused on identifying approaches used to evaluate sustainability, not a review of intervention effects comparing specific interventions. Therefore, PICO or similar intervention-comparison frameworks are not applicable."
    }
  ],
  "confidence": 100
}

